class TestDataviewItemComponent(BloomerpComponentTestCase):
    """Tests function `dataview_item` from `bloomerp/components/objects/dataviews/dataview_item.py`."""

    view_name = 'components_dataview_item'
    auto_create_customers = False

    def get_test_scenarios(self) -> list[RequestScenario]:
        """Cover single-item rendering, action refresh, and inaccessible records."""
        return [
            RequestScenario(
                name="Object action posts without list parameters and the row retains its refresh URL",
                view_name="components_objects_actions",
                method="POST",
                user=self.admin_user,
                prepare=self.prepare_complete_action,
                expected=ExpectedResult(response_validators=self.refreshes_completed_row),
            ),
            RequestScenario(
                name="A record outside the view's search results requests a full refresh",
                user=self.admin_user,
                prepare=self.prepare_signed_table,
                query_params={"q": "There is no title matching this"},
                expected=ExpectedResult(status_code=204, response_validators=self.requests_full_refresh),
            ),
            RequestScenario(
                name="The item endpoint withholds rows without view access",
                user=self.normal_user,
                prepare=self.prepare_todo,
                expected=ExpectedResult(status_code=403),
            ),
            RequestScenario(
                name="Calendar renders the same event in the period and as an individual item",
                user=self.admin_user,
                prepare=self.prepare_calendar_item,
                expected=ExpectedResult(response_validators=self.matches_calendar_placement),
            ),
            RequestScenario(
                name="A calendar event that leaves its former placement refreshes the view",
                user=self.admin_user,
                prepare=self.prepare_calendar_item,
                headers={"X-Bloomerp-Dataview-Item-Placement": "unscheduled"},
                expected=ExpectedResult(status_code=204, response_validators=self.requests_full_refresh),
            ),
            RequestScenario(
                name="Gantt renders a scheduled record and its timeline coordinates",
                user=self.admin_user,
                prepare=self.prepare_gantt_item,
                expected=ExpectedResult(response_validators=[
                    self.contains_text("data-gant-row"),
                    self.contains_text('data-gant-item'),
                    self.does_not_contain_text('data-gant-page-loader'),
                ]),
            ),
            RequestScenario(
                name="An embedded File Browser returns the associated file rather than its host record",
                user=self.admin_user,
                prepare=self.prepare_file_item,
                expected=ExpectedResult(response_validators=self.renders_embedded_file),
            ),
            RequestScenario(
                name="An embedded File Browser withholds files outside its host collection",
                user=self.admin_user,
                prepare=self.prepare_excluded_file,
                expected=ExpectedResult(status_code=204, response_validators=self.requests_full_refresh),
            ),
        ]

    def prepare_todo(self, scenario: RequestScenario) -> None:
        """Create one Todo and address it through the item endpoint."""
        self.todo = Todo.objects.create(title="Refresh this Todo", status=TodoStatus.BACKLOG)
        scenario.view_kwargs = {
            "content_type_id": ContentType.objects.get_for_model(Todo).pk,
            "object_id": self.todo.pk,
        }

    def prepare_signed_table(self, scenario: RequestScenario) -> None:
        """Use a signed table layout while the Todo defaults to a Kanban board."""
        self.prepare_todo(scenario)
        self.sign_layout(scenario, Todo, TableDataView(display_fields=["title", "status"]))

    def sign_layout(self, scenario: RequestScenario, model: type[Model], layout: BaseDataview) -> None:
        """Apply a signed inline layout and retain any existing query options."""
        self.context_headers = self.request_context_headers(
            RequestToken(
                expiry=timezone.now() + timedelta(minutes=5), dataviews={model: DataviewToken(dataview=layout)},
            ), self.admin_user,
        )
        scenario.headers = {**(scenario.headers or {}), **self.context_headers}
        scenario.query_params = scenario.query_params or {}

    def prepare_calendar_item(self, scenario: RequestScenario) -> None:
        """Set up an event and an inline calendar covering its current timeslot."""
        start = timezone.localtime().replace(hour=10, minute=0, second=0, microsecond=0)
        self.calendar_event = CalendarEvent.objects.create(
            title="Calendar refresh event", start=start, end=start + timedelta(hours=1),
            organizer_email="organizer@example.com", event_timezone=timezone.get_current_timezone_name(),
        )
        scenario.view_kwargs = {
            "content_type_id": ContentType.objects.get_for_model(CalendarEvent).pk,
            "object_id": self.calendar_event.pk,
        }
        self.sign_layout(scenario, CalendarEvent, CalendarDataView(
            calendar_view_mode="week", start_field="start", end_field="end",
            display_fields=["title"],
        ))

    def matches_calendar_placement(self, response: HttpResponse) -> bool:
        """Compare placement with the full view and exercise that placement on refresh."""
        content_type_id = ContentType.objects.get_for_model(CalendarEvent).pk
        full_view = self.client.get(reverse("components_dataview", args=[content_type_id]), headers=self.context_headers)
        select = f'[data-dataview-record][data-object-id="{self.calendar_event.pk}"]'
        full_item = BeautifulSoup(full_view.content, "html.parser").select_one(select)
        self.assertIsNotNone(full_item)
        item = BeautifulSoup(response.content, "html.parser").select_one(select)
        self.assertIsNotNone(item)
        placement = full_item["data-dataview-item-placement"]
        self.assertEqual(item["data-dataview-item-placement"], placement)
        refreshed = self.client.get(
            reverse("components_dataview_item", args=[content_type_id, self.calendar_event.pk]),
            headers={**self.context_headers, "X-Bloomerp-Dataview-Item-Placement": placement},
        )
        self.assertContains(refreshed, "Calendar refresh event")
        self.assertNotContains(refreshed, "data-calendar-grid")
        return True

    def prepare_gantt_item(self, scenario: RequestScenario) -> None:
        """Store a Gantt preference with the same date fields as the fixture event."""
        self.prepare_calendar_item(scenario)
        content_type_id = scenario.view_kwargs["content_type_id"]
        layout = GanttDataView(start_field="start", end_field="end")
        preference = UserListViewPreference.objects.create(
            name="Gantt item test", user=self.admin_user, content_type_id=content_type_id,
            view_type=layout.view_type, options={"gantt": layout.dump_options()},
        )
        scenario.query_params = {ACTION_DATAVIEW_PREFERENCE_PARAM: preference.pk}
        scenario.headers = None

    def prepare_file_item(self, scenario: RequestScenario) -> None:
        """Embed physical files in the Todo collection through a readable reference."""
        self.prepare_todo(scenario)
        self.file = FileNode.objects.create(
            name="Attached item.txt", kind="FILE",
            content=SimpleUploadedFile("attached.txt", b"content"),
        )
        FileReference.objects.create(file=self.file, content_object=self.todo)
        scenario.view_kwargs["object_id"] = self.file.pk
        self.sign_layout(scenario, Todo, FileBrowserDataview(folder_type="physical"))

    def prepare_excluded_file(self, scenario: RequestScenario) -> None:
        """Address a file with no reference in the originating collection."""
        self.prepare_file_item(scenario)
        FileReference.objects.filter(file=self.file).delete()

    def renders_embedded_file(self, response: HttpResponse) -> bool:
        """Check the row retains an item URL for the host collection and signed layout."""
        row = BeautifulSoup(response.content, "html.parser").select_one(f'tr[data-file-id="{self.file.pk}"]')
        self.assertIsNotNone(row)
        self.assertIn(self.file.name, row.get_text())
        url = urlsplit(row["data-dataview-item-url"])
        self.assertEqual(url.path, reverse("components_dataview_item", args=[
            ContentType.objects.get_for_model(Todo).pk, self.file.pk,
        ]))
        self.assertFalse(REQUEST_TOKEN_QUERY_KEYS.intersection(parse_qs(url.query)))
        return True

    def prepare_complete_action(self, scenario: RequestScenario) -> None:
        """Render a filtered table and capture the record's action and refresh URLs."""
        self.prepare_signed_table(scenario)
        scenario.view_kwargs["action_id"] = "test-complete"
        self.enterContext(patch.object(Todo.bloomerp_config, "object_actions", [
            ObjectAction(
                id="test-complete",
                label="Complete",
                execution_func=self.complete_todo,
                refresh_on_success="item",
            ),
        ]))
        view = self.client.get(
            reverse("components_dataview", args=[scenario.view_kwargs["content_type_id"]]),
            {"q": self.todo.title},
            headers=self.context_headers,
        )
        self.assertEqual(view.status_code, 200)
        row = BeautifulSoup(view.content, "html.parser").select_one(
            f'tr[data-object-id="{self.todo.pk}"]',
        )
        self.assertIsNotNone(row)
        button = row.select_one('[data-object-action-id="test-complete"]')
        self.assertIsNotNone(button)
        self.assertEqual(
            button["hx-post"], reverse("components_objects_actions", kwargs=scenario.view_kwargs),
        )
        self.item_refresh_url = row["data-dataview-item-url"]

    @staticmethod
    def complete_todo(context: ObjectActionContext) -> None:
        """Complete the fixture through an ordinary model-configured callback."""
        assert context.dataview is None
        todo = context.object
        assert isinstance(todo, Todo)
        todo.status = TodoStatus.COMPLETED
        todo.save(update_fields=["status"])

    def refreshes_completed_row(self, response: HttpResponse) -> bool:
        """Use the action event and the rendered row's URL to load the updated row."""
        event = json.loads(response["HX-Trigger-After-Swap"])["bloomerp:dataview-record-refresh"]
        self.assertEqual(event["contentTypeId"], ContentType.objects.get_for_model(Todo).pk)
        self.assertEqual(event["objectId"], str(self.todo.pk))
        self.assertTrue(event["originOnly"])
        self.assertNotIn("itemUrl", event)
        url = urlsplit(self.item_refresh_url)
        self.assertFalse(REQUEST_TOKEN_QUERY_KEYS.intersection(parse_qs(url.query)))
        self.assertEqual(parse_qs(url.query)["q"], ["Refresh this Todo"])
        item = self.client.get(self.item_refresh_url, headers={
            **self.context_headers,
            "HX-Request": "true",
            "X-Bloomerp-Dataview-Item-Index": "4",
        })
        self.assertContains(item, "Completed")
        html = BeautifulSoup(item.content, "html.parser")
        self.assertIsNone(html.find("table"))
        rows = html.select("tr[data-dataview-record][data-dataview-item-index='4']")
        self.assertEqual(len(rows), 1)
        self.assertEqual(rows[0]["data-object-id"], str(self.todo.pk))
        self.assertEqual(rows[0]["data-dataview-record-content-type-id"], str(event["contentTypeId"]))
        self.assertEqual(rows[0]["data-dataview-item-url"], self.item_refresh_url)
        return True

    @staticmethod
    def requests_full_refresh(response: HttpResponse) -> bool:
        """Check that a missing row sends no markup and asks its own view to refresh."""
        return json.loads(response["HX-Trigger"]) == {"bloomerp:dataview-refresh": {"result": "saved"}}
